y":72,"z":25},{"x":15,"y":72,"z":26}]]]}"""

    private fun obj(s: String): JsonObject = JsonParser.parseString(s).asJsonObject
    private fun arr(s: String): JsonArray = JsonParser.parseString(s).asJsonArray

    /** Question text to accepted answers. */
    val quiz: Map<String, List<String>> by lazy { obj(QUIZ_JSON).entrySet().associate { (k, v) -> k to v.asJsonArray.map { it.asString } } }

    /** The 13 lantern pairs. */
    val beams: List<IntArray> by lazy { arr(BEAMS_JSON).map { p -> p.asJsonArray.map { it.asInt }.toIntArray() } }

    /** Boulder key to `[renderX, renderZ, clickX, clickZ]` lists, in solving order. */
    val boulder: Map<String, List<IntArray>> by lazy {
        obj(BOULDER_JSON).entrySet().associate { (k, v) -> k to v.asJsonArray.map { c -> c.asJsonArray.map { it.asInt }.toIntArray() } }
    }

    /** One Ice Fill pattern of one floor: the two cells that identify it (the first is air, the second is not) and its path. */
    class IcePattern(val identifierAir: IntArray, val identifierSolid: IntArray, val easy: List<IntArray>, val hard: List<IntArray>)

    /** `iceFloors[floor][pattern]`: floors 0, 1, 2 have 4, 6 and 5 patterns. */
    val iceFloors: List<List<IcePattern>> by lazy {
        val o = obj(ICE_JSON)
        fun cell(e: com.google.gson.JsonElement) = e.asJsonObject.let { intArrayOf(it["x"].asInt, it["y"].asInt, it["z"].asInt) }
        fun path(e: com.google.gson.JsonElement) = e.asJsonArray.map { cell(it) }
        (0 until 3).map { f ->
            val ids = o.getAsJsonArray("identifier")[f].asJsonArray
            val easy = o.getAsJsonArray("easy")[f].asJsonArray
            val hard = o.getAsJsonArray("hard")[f].asJsonArray
            (0 until ids.size()).map { i -> IcePattern(cell(ids[i].asJsonArray[0]), cell(ids[i].asJsonArray[1]), path(easy[i]), path(hard[i])) }
        }
    }
}
